      titulo_puesto: oferta.title,
      empresa: oferta.company.display_name,
      salario: oferta.salary_min ? `${oferta.salary_min} - ${oferta.salary_max}` : "No especificado",
      modalidad: "Por confirmar",
      resumen: oferta.description ? oferta.description.substring(0, 200) : "",
