const ofertas = $input.all().map(item => item.json);

return ofertas.map(oferta => {
  return {
    json: {
      titulo_puesto: oferta.title || oferta.jobTitle || "",
      empresa: oferta.employer ? oferta.employer.name : "",
      salario: oferta.salary || "No especificado",
      modalidad: "Por confirmar",
      resumen: (typeof oferta.description === "string") ? oferta.description.substring(0, 200) : "",
      tipo_aplicacion: "enlace",
      enlace_o_email: oferta.url || oferta.jobUrl || "",
      plataforma: "Indeed",
      fecha_publicacion: oferta.datePublished || oferta.dateOnIndeed || ""
    }
  };
});

const ofertas = $input.all().map(item => item.json);

const palabrasRemoto = ["remote", "remoto", "teletrabajo", "100% remote", "work from home"];
const palabrasExcluir = ["hybrid", "híbrido", "hibrido", "on-site", "onsite", "presencial", "in-office"];

const ofertasFiltradas = ofertas.filter(oferta => {
  const texto = `${oferta.titulo_puesto} ${oferta.resumen}`.toLowerCase();

  // El normalizador de la fuente ya marca la modalidad en los portales que son
  // 100% remotos (RemotoJob, Jobicy, We Work Remotely, Wellfound...). Sus resúmenes
  // casi nunca dicen "remote", así que sin esto se perderían enteros.
  // Si la fuente no lo marca, seguimos buscando la palabra en el texto.
  const esRemoto = oferta.modalidad === 'Remoto'
    || palabrasRemoto.some(palabra => texto.includes(palabra));
  const esHibridoOPresencial = palabrasExcluir.some(palabra => texto.includes(palabra));

  // Estricto: tiene que ser remoto Y NO mencionar híbrido/presencial
  return esRemoto && !esHibridoOPresencial;
});

return ofertasFiltradas.map(oferta => ({ json: oferta }));

// M1 (4 sep 2026): antes leia de 'Filtro cualificación'. Ahora lee de
// 'Aplicar scoring', que pasa las mismas ofertas intactas (spread) más
// encaje_ia/motivo_ia — no cambia ningún campo que ya existiera.
const ofertasNuevas = $('Aplicar scoring').all().map(item => item.json);

const filasGuardadas = [
  ...$('Get row(s) in sheet').all(),
  ...$('Leer archivo').all()
]
  .map(item => item.json)
  .filter(row => row.id_unico || row.id_url);

const idsGuardados = new Set(
  filasGuardadas.map(row => row.id_unico).filter(Boolean)
);
const idsUrlGuardados = new Set(
  filasGuardadas.map(row => row.id_url).filter(Boolean)
);

// Rango de marcas diacriticas combinantes U+0300..U+036F, construido con
// fromCharCode para no dejar caracteres invisibles en el codigo fuente.
const DIACRITICOS = new RegExp("[" + String.fromCharCode(0x300) + "-" + String.fromCharCode(0x36f) + "]", "g");

function normalizar(texto) {
  if (!texto) return "";
  return texto
    .toLowerCase()
    .normalize("NFD").replace(DIACRITICOS, "")
    .replace(/[^a-z0-9]/g, "");
}

function hash32(clave) {
  let hash = 0;
  for (let i = 0; i < clave.length; i++) {
    hash = (hash * 31 + clave.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16);
}

// URL normalizada: minusculas, sin protocolo, sin www., sin puerto, sin
// ?query, sin #fragment, sin / final. "" si no es una URL http(s) (p. ej.
// email). Parseo con regex a proposito: `new URL()` no es fiable en el
// sandbox del Code node de esta instancia (devuelve siempre "").
function normalizarUrl(valor) {
  if (!valor || typeof valor !== "string") return "";
  const m = valor.trim().match(/^https?:\/\/([^/?#]+)([^?#]*)/i);
  if (!m) return "";
  const host = m[1].toLowerCase().replace(/^www\./, "").replace(/:\d+$/, "");
  const path = m[2].replace(/\/+$/, "");
  return (host + path).toLowerCase();
}

// Truncar `resumen` a ~800 caracteres al emitir (tarea 11 / M8): algunas
// ofertas guardan la descripcion entera (~10 KB por celda) y eso dispara el
// alto de fila que el Apps Script corrige cada hora. Se hace aqui, despues
// de todos los filtros (que miran el resumen completo), asi que no cambia
// ninguna decision pasa/descarta ni las claves de dedup. El enlace completo
// va en su columna y la generacion de CV recorta el texto a 6.000 aparte.
// Corta en el ultimo espacio si esta cerca del limite, para no partir una
// palabra, y marca el recorte con "...".
const LIMITE_RESUMEN = 800;

function truncarResumen(texto) {
  if (typeof texto !== "string" || texto.length <= LIMITE_RESUMEN) return texto;
  const cortado = texto.slice(0, LIMITE_RESUMEN);
  const ultimoEspacio = cortado.lastIndexOf(" ");
  const base = ultimoEspacio > LIMITE_RESUMEN - 120 ? cortado.slice(0, ultimoEspacio) : cortado;
  return base.replace(/\s+$/, "") + "...";
}

const ofertasConId = ofertasNuevas
  .filter(oferta => oferta.empresa && oferta.titulo_puesto)
  .map(oferta => {
    const clave = normalizar(oferta.empresa) + normalizar(oferta.titulo_puesto);
    const urlNorm = normalizarUrl(oferta.enlace_o_email);
    return {
      ...oferta,
      resumen: truncarResumen(oferta.resumen),
      id_unico: hash32(clave),
      id_url: urlNorm ? hash32(urlNorm) : "",
      fecha_guardado: new Date().toISOString().split('T')[0],
      estado: "pendiente",
      generar_cv_ia: false
    };
  });

const idsDeEstaTanda = new Set();
const idsUrlDeEstaTanda = new Set();

const ofertasSinDuplicar = ofertasConId.filter(oferta => {
  if (idsGuardados.has(oferta.id_unico)) return false;
  if (oferta.id_url && idsUrlGuardados.has(oferta.id_url)) return false;
  if (idsDeEstaTanda.has(oferta.id_unico)) return false;
  if (oferta.id_url && idsUrlDeEstaTanda.has(oferta.id_url)) return false;
  idsDeEstaTanda.add(oferta.id_unico);
  if (oferta.id_url) idsUrlDeEstaTanda.add(oferta.id_url);
  return true;
});

return ofertasSinDuplicar.map(oferta => ({ json: oferta }));

const errores = $input.all();

// Si no hay ningún error, no seguimos generando nada
if (errores.length === 0) {
  return [];
}

// Construimos un mensaje simple listando qué falló.
// n8n entrega el error unas veces como objeto {message} y otras como string.
const lineas = errores.map(item => {
  const e = item.json.error;
  const mensaje = (typeof e === "string" ? e : e?.message)
    || item.json.message
    || "Error desconocido";
  return `<li>${mensaje}</li>`;
});

const html = `
  <h2>⚠️ Aviso: hubo un problema al buscar ofertas</h2>
  <p>Al menos una fuente de ofertas falló hoy. Detalle:</p>
  <ul>
    ${lineas.join("")}
  </ul>
  <p>El resto del workflow siguió funcionando con normalidad usando las fuentes que sí respondieron.</p>
`;

return [{ json: { html_alerta: html } }];

const SALARIO_MINIMO_EUR = 22000; // umbral en euros/ano (22 oct 2026: bajado de 33000, decision de Mar)

// Tasas de conversion aproximadas a EUR (no hay API de tipos de cambio conectada al proyecto).
const TASAS_A_EUR = {
    EUR: 1,
    USD: 0.92,
    GBP: 1.17,
};

function detectarMoneda(texto) {
    if (texto.includes('£') || /\bGBP\b/i.test(texto)) return 'GBP';
    if (texto.includes('$') || /\bUSD\b/i.test(texto)) return 'USD';
    return 'EUR'; // fuentes sin moneda explicita (Adzuna, InfoJobs) buscan en Espana
}

function parseSalario(salarioTexto) {
    if (!salarioTexto || salarioTexto.toLowerCase().includes('no especificado')) {
        return { conocido: false, valor: null };
    }

    // Normaliza separadores de miles en formato espanol: "30.000" -> "30000"
    const textoNormalizado = salarioTexto.replace(/(\d)\.(\d{3})(?!\d)/g, '$1$2');

    const numeros = textoNormalizado.match(/\d+(\.\d+)?/g);
    if (!numeros || numeros.length === 0) {
        return { conocido: false, valor: null };
    }

    const moneda = detectarMoneda(salarioTexto);
    const tasa = TASAS_A_EUR[moneda];

    // Los normalizadores de fuente no son consistentes: unos entregan el salario
    // ya en unidades completas (Adzuna: "30000 - 45000") y otros en formato
    // abreviado ("30 - 45", o "120K" tipo Wellfound). Un numero por debajo de
    // 1000 solo tiene sentido como miles; uno igual o mayor ya esta completo.
    const valoresReales = numeros.map(n => {
        const valor = parseFloat(n);
        return valor < 1000 ? valor * 1000 : valor;
    });
    const promedio = valoresReales.reduce((a, b) => a + b, 0) / valoresReales.length;

    return { conocido: true, valor: promedio * tasa };
}

const ofertas = $input.all().map(item => item.json);

const ofertasFiltradas = ofertas.filter(oferta => {
    const { conocido, valor } = parseSalario(oferta.salario);
    if (!conocido) return true; // sin dato -> pasa
    return valor >= SALARIO_MINIMO_EUR;
});

return ofertasFiltradas.map(oferta => ({ json: oferta }));

const ofertas = $input.all().map(item => item.json);
return ofertas.map(oferta => {
  return {
    json: {
      titulo_puesto: oferta.title || "",
      empresa: oferta.companyName || "",
      salario: oferta.salary || "No especificado",
      modalidad: "Por confirmar",
      resumen: (typeof oferta.description === "string") ? oferta.description.substring(0, 200) : "",
      tipo_aplicacion: "enlace",
      enlace_o_email: oferta.url || "",
      plataforma: "LinkedIn",
      fecha_publicacion: oferta.postedDate || ""
    }
  };
});

const ofertas = $input.all().map(item => item.json);
return ofertas.map(oferta => {
  const salario = (oferta.salary_min || oferta.salary_max)
    ? `${oferta.salary_min || '?'} - ${oferta.salary_max || '?'} ${oferta.salary_currency || ''} / ${oferta.salary_period || ''}`.trim()
    : "No especificado";
  return {
    json: {
      titulo_puesto: oferta.title || "",
      empresa: oferta.company_name || "",
      salario: salario,
      modalidad: "Por confirmar",
      resumen: (typeof oferta.description_text === "string") ? oferta.description_text.substring(0, 200) : "",
      tipo_aplicacion: "enlace",
      enlace_o_email: oferta.offer_url || "",
      plataforma: "Infojobs",
      fecha_publicacion: oferta.published_at || ""
    }
  };
});

// Himalayas envuelve las ofertas dentro de un campo "jobs" — hay que abrir esa capa primero
const respuesta = $input.first().json;
const ofertas = respuesta.jobs || [];

return ofertas.map(oferta => {
  const salario = (oferta.minSalary || oferta.maxSalary)
    ? `${oferta.minSalary || '?'} - ${oferta.maxSalary || '?'} ${oferta.currency || ''} / ${oferta.salaryPeriod || ''}`.trim()
    : "No especificado";

  // pubDate viene como timestamp (segundos desde 1970), lo convertimos a fecha normal
  const fecha = oferta.pubDate ? new Date(oferta.pubDate * 1000).toISOString() : "";

  return {
    json: {
      titulo_puesto: oferta.title || "",
      empresa: oferta.companyName || "",
      salario: salario,
      modalidad: "Remoto",
      resumen: (typeof oferta.excerpt === "string") ? oferta.excerpt.substring(0, 200) : "",
      tipo_aplicacion: "enlace",
      enlace_o_email: oferta.applicationLink || "",
      plataforma: "Himalayas",
      fecha_publicacion: fecha
    }
  };
});

// Normalizador para el actor "All Jobs Scraper" (Jooble, Glassdoor, SAP, Talent.com)
// Convierte cada oferta al formato común del proyecto y descarta lo que no sirve.

// Intenta arreglar tildes/ñ rotas (ej: "a¤adan" en vez de "añadan").
// Es un arreglo best-effort: no garantizamos que corrija el 100% de los casos,
// pero soluciona el patrón más común que vimos en los datos de Jooble.
function arreglarCodificacion(texto) {
  if (!texto) return texto;
  try {
    const arreglado = Buffer.from(texto, 'latin1').toString('utf8');
    // Si el resultado tiene menos caracteres de reemplazo raros que el original, usamos el arreglado
    return arreglado;
  } catch (e) {
    return texto;
  }
}

// Decide la modalidad de trabajo combinando dos campos, porque "is_remote" solo
// no es de fiar (vimos casos de SAP marcados is_remote:true siendo en realidad híbridos).
function calcularModalidad(item) {
  const wfh = (item.work_from_home || '').toLowerCase();

  if (wfh === 'remote') return 'Remoto';
  if (wfh === 'hybrid') return 'Híbrido';
  if (wfh === 'on-site' || wfh === 'onsite') return 'Presencial';

  // No hay dato claro de work_from_home (caso Talent.com): no descartamos,
  // lo dejamos como "Por confirmar" para que pase el filtro de salario/palabras clave.
  return 'Por confirmar';
}

// Detecta ofertas caducadas de Jooble ("Este trabajo ya no está disponible...")
function esOfertaCaducada(descripcion) {
  if (!descripcion) return false;
  const inicio = descripcion.trim().toLowerCase().slice(0, 60);
  return inicio.includes('ya no est') && inicio.includes('disponible');
}

function construirSalario(item) {
  if (item.salary_minimum && item.salary_maximum) {
    const moneda = item.salary_currency || '';
    return `${item.salary_minimum} - ${item.salary_maximum} ${moneda}`.trim();
  }
  if (item.salary_minimum) {
    return `Desde ${item.salary_minimum} ${item.salary_currency || ''}`.trim();
  }
  return 'No especificado';
}

const ofertasNormalizadas = [];

for (const entrada of $input.all()) {
  const item = entrada.json;

  // Item fantasma vacío o sin título: lo saltamos (bug ya conocido del proyecto)
  if (!item || !item.title) continue;

  // Descartar ofertas caducadas
  if (esOfertaCaducada(item.description)) continue;

  const oferta = {
    titulo_puesto: arreglarCodificacion(item.title),
    empresa: arreglarCodificacion(item.company_name) || 'No especificado',
    salario: construirSalario(item),
    modalidad: calcularModalidad(item),
    // Resumen provisional cortando el inicio de la descripción (pendiente de que
    // lo genere la IA más adelante, ya está anotado en la sección 12 del resumen)
    resumen: arreglarCodificacion((item.description || '').slice(0, 300)),
    tipo_aplicacion: 'enlace',
    enlace_o_email: item.official_url || item.platform_url || '',
    plataforma: item.platform || 'Desconocida',
    fecha_publicacion: item.posted_date || ''
  };

  ofertasNormalizadas.push(oferta);
}

return ofertasNormalizadas.map(oferta => ({ json: oferta }));

const ofertas = [];

for (const item of $input.all()) {
  const data = item.json;

  // "Empresa: Puesto" viene junto en el campo title.
  // Buscamos la posición del PRIMER ":" para partirlo en dos.
  const tituloCompleto = data.title || '';
  const indiceDosPuntos = tituloCompleto.indexOf(':');

  let empresa = '';
  let puesto = '';

  if (indiceDosPuntos !== -1) {
    empresa = tituloCompleto.substring(0, indiceDosPuntos).trim();
    puesto = tituloCompleto.substring(indiceDosPuntos + 1).trim();
  } else {
    // Por si alguna vez llega sin ":" (raro, pero mejor no romper el flujo)
    puesto = tituloCompleto.trim();
    empresa = 'No especificado';
  }

  ofertas.push({
    json: {
      titulo_puesto: puesto,
      empresa: empresa,
      salario: 'No especificado',       // WWR nunca trae salario
      modalidad: 'Remoto',              // WWR es 100% remoto por definición
      resumen: data.contentSnippet || '', // texto limpio, sin etiquetas HTML
      tipo_aplicacion: 'enlace',
      enlace_o_email: data.link || '',
      plataforma: 'We Work Remotely',
      fecha_publicacion: data.isoDate || data.pubDate || ''
    }
  });
}

return ofertas;

// ===========================================================================
// Filtro cualificación — decide si una oferta encaja con el perfil de Mar.
//
// Cambio de fondo (14 ago 2026): antes esto era una LISTA NEGRA (descartaba
// lo que mencionaba "frontend", "abogado"... y dejaba pasar TODO lo demás),
// así que se colaban puestos de cualquier profesión no enumerada. Ahora una
// oferta tiene que GANARSE la entrada: además de no caer en ninguna lista de
// descarte, su título debe encajar con alguna familia objetivo.
//
// Se descarta por, en este orden:
//   1. idioma   — exige un idioma que Mar no habla (habla ES, CA y EN)
//   2. contrato — freelance, autónomo, part-time, prácticas
//   3. nivel    — senior, lead, head, director, VP, chief... o +4 años de experiencia
//   4. perfil   — profesión fuera de perfil: exclusión dura (4a), exclusión
//                 blanda (4b) o ingeniería técnica (4c)
//   5. encaje   — el título no menciona ninguna familia objetivo (lista blanca)
//
// Calibrado contra las 248 ofertas reales de la ejecución #572 (14 ago 2026):
// pasaban 174, luego pasaban 15.
//
// 10 sep 2026 (tarea 17): nuevo criterio 4c «ingeniería técnica». Entraban
// roles técnicos que solo mencionan «AI» en el título (Kubernetes/Cloud
// Integration Engineer, Agentic Python Engineer, Ingeniero de IA Generativa…)
// porque el criterio 5 los rescataba por la familia IA. Decisiones de Mar en
// docs/mejora-filtro-cualificacion.md.
//
// Todas las listas son editables: son arrays de palabras y nada más.
// ===========================================================================

// --- 1. Idiomas que Mar NO habla ------------------------------------------
const IDIOMAS_NO_HABLADOS = [
  'german', 'deutsch', 'aleman', 'french', 'francais', 'frances',
  'dutch', 'nederlands', 'neerlandes', 'holandes', 'italian', 'italiano',
  'portuguese', 'portugues', 'polish', 'polaco', 'swedish', 'sueco',
  'danish', 'danes', 'norwegian', 'noruego', 'finnish', 'fines',
  'russian', 'ruso', 'chinese', 'mandarin', 'chino', 'japanese', 'japones',
  'korean', 'coreano', 'arabic', 'arabe', 'turkish', 'turco',
  'czech', 'checo', 'romanian', 'rumano', 'hungarian', 'hungaro',
  'greek', 'griego', 'hebrew', 'hebreo', 'ukrainian', 'ucraniano',
];

// Un idioma solo descarta si aparece CERCA de una marca de requisito.
// Sin esto, un "we serve the German market" tiraría una oferta perfecta.
const MARCAS_DE_REQUISITO = [
  'fluent', 'fluency', 'native', 'speaker', 'speaking', 'proficiency',
  'proficient', 'bilingual', 'mother tongue', 'must speak', 'required',
  'requirement', 'nivel alto', 'imprescindible', 'se requiere', 'requiere',
  'dominio', 'nativo', 'nativa', 'hablar', 'c1', 'c2', 'b2',
];

// --- 2. Contratos que no interesan ----------------------------------------
const CONTRATOS_FUERA = [
  'freelance', 'freelancer', 'autonomo', 'self employed', 'contractor',
  'independent contractor', 'part time', 'media jornada', 'por horas',
  'internship', 'intern', 'becario', 'becaria', 'practicas', 'trainee',
  'voluntario', 'volunteer', 'temporary', 'temporal',
];

// --- 3. Nivel por encima del perfil ---------------------------------------
const NIVELES_FUERA = [
  'senior', 'sr', 'lead', 'leader', 'principal', 'staff',
  'head of', 'head', 'director', 'directora', 'director/a',
  'vp', 'vice president', 'chief', 'cto', 'ceo', 'coo', 'cfo', 'cmo',
  'founder', 'cofounder', 'co founder', 'partner', 'expert', 'architect',
  'arquitecto', 'especialista senior', 'iv', 'iii',
];

// Excepciones: títulos que contienen una palabra de arriba sin ser un puesto
// por encima del perfil.
const NIVELES_EXCEPCION = ['semi senior', 'semisenior', 'junior', 'jr'];

// --- 4a. Profesiones fuera de perfil: exclusión DURA ----------------------
// Oficios que requieren una carrera que Mar no tiene. Mencionar "AI" o
// "automation" en el título NO los rescata: un "Applied AI Developer" sigue
// siendo un puesto de desarrollo. Ojo con "engineer": va por compuestos
// concretos, para que "Automation Engineer" (que sí es su perfil: n8n, Make,
// Zapier) no caiga aquí por accidente. El "engineer"/"ingeniero" a secas lo
// filtra el criterio 4c, no este.
// 10 sep 2026 (tarea 17): fuera "ai engineer" e "ingeniero de inteligencia
// artificial" — ahora pasan al scoring "encaje_ia" (decisión de Mar del 6 sep:
// "AI Engineer sí, ML Engineer no"). "ml engineer" / "machine learning
// engineer" se quedan. Añadidos kubernetes / python engineer / enablement
// engineer / monitorización… que colaban por el criterio 5.
const EXCLUSION_DURA = [
  // desarrollo de software
  'full stack', 'fullstack', 'frontend', 'front end', 'backend', 'back end',
  'developer', 'desarrollador', 'desarrolladora', 'programador', 'programadora',
  'development talent', 'devops', 'sysadmin', 'sre', 'site reliability',
  'software engineer', 'ingeniero de software', 'ml engineer',
  'machine learning engineer', 'data engineer', 'cloud engineer',
  'security engineer', 'qa engineer', 'backend engineer', 'frontend engineer',
  'platform engineer', 'devops engineer', 'test engineer', 'network engineer',
  'systems engineer', 'solutions engineer', 'support engineer',
  'civil engineer', 'mechanical engineer', 'electrical engineer',
  'sales engineer', 'ingeniero civil', 'ingeniero de datos',
  'mobile', 'ios', 'android', 'react', 'angular', 'vue', 'node js', 'java',
  'php', 'ruby', 'golang', 'rust',
  'qa', 'tester', 'testing', 'cybersecurity', 'ciberseguridad',
  'blockchain', 'web3', 'infrastructure', 'infraestructura',
  'database administrator',
  // técnicos que se colaban por el criterio 5 (tarea 17, 10 sep 2026)
  'kubernetes', 'k8s', 'cloud integration', 'integration engineer',
  'python engineer', 'python developer', 'programmer', 'enablement engineer',
  'monitorizacion', 'monitoring', 'observability', 'observabilidad',
  // datos y consultoría técnica
  'data scientist', 'scientist', 'bi consultant', 'business intelligence',
  'big data', 'sap', 'salesforce', 'vtex', 'outsystems', 'openshift',
  'oracle', 'sharepoint', 'dynamics', 'erp', 'openpages', 'servicenow',
  'workday',
  // diseño y audiovisual
  'designer', 'disenador', 'disenadora', 'diseno grafico', 'ux', 'ui',
  'illustrator', 'ilustrador', 'ilustradora', 'video editor',
  'editor de video', 'videographer', 'motion', 'animator', 'fotografo',
  'photographer',
  // sanidad
