// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------

// Pasa a minúsculas, quita acentos y convierte guiones y barras en espacios,
// para que "Automatización" case con "automatizacion" y "no-code" con "no code".
function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .replace(/[-_/.,;:()\[\]|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Cache de expresiones regulares: se compilan una vez, no 248 veces.
const cacheRegex = new Map();
function regexDe(termino) {
  if (!cacheRegex.has(termino)) {
    const limpio = normalizar(termino).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    cacheRegex.set(termino, new RegExp(`\\b${limpio}\\b`));
  }
  return cacheRegex.get(termino);
}

// Busca palabras completas: "ai" no casa dentro de "email" ni "training".
function buscar(textoNormalizado, lista) {
  for (const termino of lista) {
    if (regexDe(termino).test(textoNormalizado)) return termino;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Los cinco criterios
// ---------------------------------------------------------------------------

// 1. Idioma: descarta solo si el idioma aparece a menos de 40 caracteres de
//    una marca de requisito. También detecta los marcadores de género de las
//    ofertas alemanas (m/w/d, en cualquier orden: (f/m/d), (w/m/d)...) y
//    francesas (H/F), que son inequívocos.
//    17 ago 2026: el orden fijo "m" primero se colaba con "(f/m/d)" —
//    variante habitual en ofertas alemanas publicadas en inglés (female/
//    male/diverse en vez de Mann/Frau/Divers). Ver la oferta de ecosio en
//    jobs-ingesta.md, Fallos conocidos.
function motivoIdioma(tituloCrudo, textoNormalizado) {
  if (/\(\s*[mwfdx]\s*[/|]\s*[mwfdx]\s*[/|]\s*[mwfdx]\s*\)/i.test(tituloCrudo)) {
    return 'idioma: oferta alemana (m/w/d)';
  }
  if (/\(\s*h\s*\/\s*f\s*\)/i.test(tituloCrudo)) {
    return 'idioma: oferta francesa (H/F)';
  }

  // 17 ago 2026: si el TÍTULO por sí solo menciona 2+ idiomas no hablados,
  // la propia enumeración ya es el requisito — no hace falta que aparezca
  // una marca cerca ("with English and German/French/Italian" no trae
  // "fluent" ni "required", pero listar tres idiomas ya lo dice todo). Solo
  // se mira el título, no el resumen, para no descartar ofertas que solo
  // listan mercados o países en el cuerpo del texto. Probado sin falsos
  // positivos contra títulos con "DACH"/"EMEA"/nombres de país. Ver
  // tareas-manuales.md, punto B (decisión cerrada esta fecha).
  const tituloSolo = normalizar(tituloCrudo);
  const idiomasEnTitulo = new Set();
  for (const idioma of IDIOMAS_NO_HABLADOS) {
    if (regexDe(idioma).test(tituloSolo)) idiomasEnTitulo.add(idioma);
  }
  if (idiomasEnTitulo.size >= 2) {
    return `idioma: título lista ${[...idiomasEnTitulo].join('/')}`;
  }

  for (const idioma of IDIOMAS_NO_HABLADOS) {
    const encaje = regexDe(idioma).exec(textoNormalizado);
    if (!encaje) continue;

    const desde = Math.max(0, encaje.index - 40);
    const ventana = textoNormalizado.slice(desde, encaje.index + idioma.length + 40);
    if (buscar(ventana, MARCAS_DE_REQUISITO)) {
      return `idioma: exige ${idioma}`;
    }
  }
  return '';
}

// 3b. Años de experiencia: solo cuenta si el número va acompañado de la
//     palabra "experiencia", y no descarta si son años de operaciones,
//     que es justo donde Mar tiene 7.
function motivoAnnos(textoNormalizado) {
  const patron = /(\d{1,2})\s*\+?\s*(?:anos|years|yrs)/g;
  let encaje;

  while ((encaje = patron.exec(textoNormalizado)) !== null) {
    const annos = parseInt(encaje[1], 10);
    if (annos <= 4) continue;

    const ventana = textoNormalizado.slice(
      Math.max(0, encaje.index - 30),
      encaje.index + 60
    );
    if (!/experien/.test(ventana)) continue;
    if (buscar(ventana, ['operations', 'operaciones', 'admin', 'coordination', 'coordinacion'])) {
      continue;
    }
    return `nivel: pide ${annos} años de experiencia`;
  }
  return '';
}

