const ofertasFiltradas = [];
const descartes = [];
// Desglose de descartes por fuente y criterio, para la pestaña Metricas
// (tarea 10 / M3). Se publica en workflowStaticData al final: el nodo
// "Registrar métricas" (rama aislada tras "Filtro duplicados") lo lee desde
// ahí — $('Filtro cualificación').all() solo expone los items de salida, no
// estas variables internas.
const descartesPorFuente = {};

for (const item of $input.all()) {
  const oferta = item.json;

  const titulo = normalizar(oferta.titulo_puesto);
  const completo = normalizar(`${oferta.titulo_puesto || ''} ${oferta.resumen || ''}`);

  let motivo = '';

  // 1. Idioma (título + resumen: los requisitos de idioma van en el cuerpo)
  motivo = motivoIdioma(oferta.titulo_puesto || '', completo);

  // 2. Contrato (solo título)
  if (!motivo) {
    const contrato = buscar(titulo, CONTRATOS_FUERA);
    if (contrato) motivo = `contrato: ${contrato}`;
  }

  // 3. Nivel (título, más los años de experiencia en el texto completo)
  if (!motivo && !buscar(titulo, NIVELES_EXCEPCION)) {
    const nivel = buscar(titulo, NIVELES_FUERA);
    if (nivel) motivo = `nivel: ${nivel}`;
  }
  if (!motivo) motivo = motivoAnnos(completo);

  // 4a. Profesión fuera de perfil, exclusión dura (no la salva nada)
  if (!motivo) {
    const dura = buscar(titulo, EXCLUSION_DURA);
    if (dura) motivo = `perfil: ${dura}`;
  }

  // 4b. Exclusión blanda: solo si el título no trae una señal de rescate
  if (!motivo && !buscar(titulo, RESCATE)) {
    const blanda = buscar(titulo, EXCLUSION_BLANDA);
    if (blanda) motivo = `perfil: ${blanda}`;
  }

  // 4c. Ingeniería técnica: "engineer"/"ingeniero" a secas sin señal de
  //     automatización/operaciones; "data ops" sin IA aplicada; o marcador
  //     de investigación/modelado aunque haya rescate.
  if (!motivo) {
    const ing = buscar(titulo, SENAL_INGENIERIA);
    if (ing) {
      const rescate = buscar(titulo, RESCATE_INGENIERIA);
      const dataOps = buscar(titulo, DATA_OPS);
      const mencionaIA = buscar(titulo, SENAL_IA_APLICADA);
      const investigacion = buscar(titulo, INGENIERIA_INVESTIGACION);
      if (investigacion) {
        motivo = `perfil: título de investigación/modelado (${investigacion})`;
      } else if (dataOps && !mencionaIA) {
        motivo = `perfil: ${dataOps} sin IA aplicada`;
      } else if (!rescate) {
        motivo = `perfil: ${ing} sin señal de automatización/operaciones`;
      }
    }
  }

  // 5. Requisito positivo: el título tiene que sonar a algo del perfil
  if (!motivo && !buscar(titulo, FAMILIAS_OBJETIVO)) {
    motivo = 'encaje: el título no encaja con ninguna familia objetivo';
  }

  if (motivo) {
    descartes.push(`${motivo}  ←  ${oferta.titulo_puesto}`);
    const criterio = motivo.split(':')[0].trim();
    const fuente = oferta.plataforma || 'desconocida';
    if (!descartesPorFuente[fuente]) descartesPorFuente[fuente] = {};
    descartesPorFuente[fuente][criterio] = (descartesPorFuente[fuente][criterio] || 0) + 1;
    continue;
  }

  oferta.destacada = buscar(titulo, SENALES_DESTACADA) ? '⭐' : '';
  ofertasFiltradas.push({ json: oferta });
}

// Rastro para calibrar: n8n guarda estos logs en el panel de la ejecución,
