// Cada item de entrada es la pagina HTML de una oferta (el HTTP Request usa
// responseFormat "text", asi que el cuerpo llega en data). Todo sale del
// JSON-LD de schema.org que incrusta la pagina: titulo, empresa, fecha y
// descripcion. RemotoJob ya no tiene RSS (cambio de web), el enlace viene de
// "Extraer enlaces RemotoJob". Sin la empresa, Jobs - seguimiento no puede
// cruzar las respuestas con su candidatura.
const entradas = $input.all();
const ofertas = [];

function extraerJobPosting(html) {
  const bloques = html.matchAll(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g);
  for (const bloque of bloques) {
    // El JSON-LD de RemotoJob NO es JSON valido: mete saltos de linea y
    // tabuladores crudos dentro de los strings (en description sobre todo) y
    // JSON.parse los rechaza. Fuera de un string esos caracteres solo son
    // espacio en blanco, asi que cambiarlos todos por un espacio arregla el
    // literal roto sin tocar la estructura.
    const saneado = Array.from(bloque[1], c => c.charCodeAt(0) < 32 ? ' ' : c).join('');
    let datos;
    try { datos = JSON.parse(saneado); } catch (e) { continue; }
    const candidatos = Array.isArray(datos) ? datos : (datos['@graph'] || [datos]);
    const oferta = candidatos.find(d => d && d['@type'] === 'JobPosting');
    if (oferta) return oferta;
  }
  return null;
}

function aTexto(html) {
  return String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

for (let i = 0; i < entradas.length; i++) {
  // itemMatching sigue el pairedItem, asi que una pagina que falle no
  // descuadra el emparejamiento de las demas.
  let listado = {};
  try { listado = $('Extraer enlaces RemotoJob').itemMatching(i).json; } catch (e) { listado = {}; }

  const html = typeof entradas[i].json.data === 'string' ? entradas[i].json.data : '';
  const jobPosting = html ? extraerJobPosting(html) : null;
  if (!jobPosting || !jobPosting.title) continue;

  ofertas.push({
    json: {
      titulo_puesto: String(jobPosting.title).trim(),
      empresa: (jobPosting.hiringOrganization && jobPosting.hiringOrganization.name) || 'No especificado',
      // RemotoJob publica baseSalary en el JSON-LD, pero el dato esta roto en
      // origen: 16 de 20 ofertas dicen exactamente 1000 EUR/MONTH (relleno del
      // portal) y el resto trae rangos concatenados sin separador (7500095000 =
      // 75000 y 95000), todos etiquetados MONTH aunque sean anuales. Usarlo
      // hundiria RemotoJob de 15 filas a 2 por salarios falsos, asi que no se usa.
      salario: 'No especificado',
      modalidad: 'Remoto',             // RemotoJob es 100% teletrabajo por definicion
      resumen: aTexto(jobPosting.description),
      tipo_aplicacion: 'enlace',
      enlace_o_email: jobPosting.url || listado.link || '',
      plataforma: 'RemotoJob',
      fecha_publicacion: jobPosting.datePosted || ''
    },
    pairedItem: { item: i }
  });
}

return ofertas;

const ofertas = [];

// La respuesta viene envuelta: { jobs: [ { jobTitle, companyName, ... } ] }
const items = $input.first().json.jobs || [];

for (const j of items) {
  // Salario: solo si Jobicy publica mínimo Y máximo, y siempre es anual
  let salario = 'No especificado';
  if (j.annualSalaryMin && j.annualSalaryMax) {
    salario = `${j.annualSalaryMin} - ${j.annualSalaryMax} ${j.salaryCurrency || 'USD'}`;
  }

  ofertas.push({
    json: {
      titulo_puesto: j.jobTitle || '',
      empresa: j.companyName || 'No especificado',
      salario: salario,
      modalidad: 'Remoto',             // Jobicy solo publica ofertas remotas
      resumen: j.jobExcerpt || '',
      tipo_aplicacion: 'enlace',
      enlace_o_email: j.url || '',
      plataforma: 'Jobicy',
      fecha_publicacion: j.pubDate || ''
    }
  });
}

return ofertas;

// API oficial de Jooble (jooble.org/api), gratuita — sustituye a la porcion de
// Jooble que antes traia el actor de pago "All Jobs Scraper" en Apify.
const ofertas = $input.first().json.jobs || [];

return ofertas.map(oferta => {
  return {
    json: {
      titulo_puesto: oferta.title || "",
      empresa: oferta.company || "",
      salario: oferta.salary || "No especificado",
